window.docContents[87].resolve({"/Cliques/#section-clique-and-independence-number-of-the-mycielskian":{"contents":"Recall from Mycielskian Mycielski's two facts: if G is\ntriangle-free then so is mμ(G), and if G has chromatic number k then mμ(G)\nhas chromatic number k + 1. In this section we prove the first fact, and more\ngenerally that the Mycielskian preserves the clique number. The second fact is\nchromaticNumber_mycielskian in the next chapter. Together they show that the\nclique number can be a very poor lower bound for the chromatic number. We finish by\ncomputing the independence number of mμ(G).\n\n\n\n\n\n\n\n","context":"Graph Theory in Lean\u0009Cliques","header":"6.7. Clique and Independence Number of the Mycielskian","id":"/Cliques/#section-clique-and-independence-number-of-the-mycielskian"},"/Colorings/#section-colouring-concrete-graphs":{"contents":"\n\n\n\n\n\n","context":"Graph Theory in Lean\u0009Colorings","header":"7.5. Colouring Concrete Graphs","id":"/Colorings/#section-colouring-concrete-graphs"}});